#pragma once
#include "types.h"

/* ========================================
 * FreeLang AST Node Definitions
 * ======================================== */

typedef enum {
    /* Statements */
    STMT_VAR_DECL,
    STMT_EXPR,
    STMT_RETURN,
    STMT_IF,
    STMT_WHILE,
    STMT_FOR,
    STMT_BLOCK,

    /* Struct and top-level */
    STMT_STRUCT_DEF,

    /* Expressions */
    EXPR_LITERAL,       /* int, float, string */
    EXPR_VAR,           /* variable reference */
    EXPR_BINARY,        /* a + b, a * b, etc */
    EXPR_UNARY,         /* -a, !a, *a, &a */
    EXPR_CALL,          /* fn(args) */
    EXPR_INDEX,         /* arr[i] */
    EXPR_MEMBER,        /* obj.field */
} NodeKind;

typedef struct Expr Expr;
typedef struct Stmt Stmt;

/* ---- Expressions ---- */

typedef struct {
    long long ival;  /* int literal */
} LiteralInt;

typedef struct {
    double fval;     /* float literal */
} LiteralFloat;

typedef struct {
    const char *sval;  /* string literal */
} LiteralString;

typedef struct {
    const char *name;  /* variable name */
} VarRef;

typedef struct {
    Expr *left;
    Expr *right;
    const char *op;    /* "+", "-", "*", "/", etc */
} BinaryOp;

typedef struct {
    Expr *operand;
    const char *op;    /* "-", "!", "*", "&" */
} UnaryOp;

typedef struct {
    const char *func_name;
    Expr **args;
    int arg_count;
} FuncCall;

typedef struct {
    Expr *array;
    Expr *index;
} IndexOp;

typedef struct {
    Expr *object;
    const char *field;
} MemberOp;

typedef struct Expr {
    NodeKind kind;
    FlType *type;  /* resolved type */

    union {
        LiteralInt lit_int;
        LiteralFloat lit_float;
        LiteralString lit_string;
        VarRef var;
        BinaryOp binary;
        UnaryOp unary;
        FuncCall call;
        IndexOp index;
        MemberOp member;
    };
} Expr;

/* ---- Statements ---- */

typedef struct {
    const char *name;
    FlType *type;
    Expr *init;        /* initializer, may be NULL */
} VarDecl;

typedef struct {
    Expr *value;       /* may be NULL for void return */
} ReturnStmt;

typedef struct {
    Expr *condition;
    Stmt *then_body;
    Stmt *else_body;   /* may be NULL */
} IfStmt;

typedef struct {
    Expr *condition;
    Stmt *body;
} WhileStmt;

typedef struct {
    const char *var_name;
    Expr *start;
    Expr *end;
    Stmt *body;
} ForStmt;

typedef struct {
    Stmt **stmts;
    int count;
} BlockStmt;

/* Struct field definition */
typedef struct {
    const char *name;
    FlType *type;
} StructField;

/* Struct definition */
typedef struct {
    const char *name;
    StructField **fields;
    int field_count;
} StructDef;

