#include "../include/types.h"
#include "../include/codegen.h"
#include "../include/parser.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* FreeLang to C transpiler - Phase 3: Full pipeline */

/* Read entire file into memory */
static char *read_file(const char *filename) {
    FILE *f = fopen(filename, "rb");
    if (!f) {
        perror("Cannot open input file");
        return NULL;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *buffer = malloc(size + 1);
    if (!buffer) {
        perror("Memory allocation failed");
        fclose(f);
        return NULL;
    }

    size_t read = fread(buffer, 1, size, f);
    buffer[read] = '\0';
    fclose(f);

    return buffer;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input.fl> [-o output.c]\n", argv[0]);
        fprintf(stderr, "Example: %s examples/fib.fl -o fib.c\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = "output.c";

    /* Parse output file option */
    for (int i = 2; i < argc - 1; i++) {
        if (strcmp(argv[i], "-o") == 0) {
            output_file = argv[i + 1];
        }
    }

    printf("📖 Reading %s...\n", input_file);

    /* Read input file */
    char *source = read_file(input_file);
    if (!source) {
        return 1;
    }

    printf("✓ Read %zu bytes\n", strlen(source));
    printf("🔍 Parsing...\n");

    /* Parse to AST */
    Parser *parser = parser_new(source);
    Program *program = parse_program(parser);
    parser_free(parser);

    if (!program || program->func_count == 0) {
        fprintf(stderr, "Parse error: No valid program\n");
        free(source);
        return 1;
    }

    printf("✓ Parsed %d function(s)\n", program->func_count);
    printf("💻 Generating C code...\n");

    /* Generate C code */
    FILE *out = fopen(output_file, "w");
    if (!out) {
        perror("Cannot open output file");
        program_free(program);
        free(source);
        return 1;
    }

    Codegen *cg = codegen_new(out);
    codegen_program(cg, program);
    codegen_free(cg);
    fclose(out);

    printf("✓ Generated %s\n", output_file);
    printf("✨ Transpilation complete!\n\n");

    /* Cleanup */
    program_free(program);
    free(source);

    return 0;
}

