/* Phase 3: Error Handling Test */

extern fn printf(fmt: *i64) -> i64;

fn divide(a: i64, b: i64) -> i64 {
    if (b == 0) {
        return -1;  /* error: division by zero */
    }
    return a / b;
}

fn safe_divide(a: i64, b: i64) -> i64 {
    var result: i64 = divide(a, b);
    if (result == -1) {
        return 0;  /* handle error: return 0 */
    }
    return result;
}

fn main() -> i64 {
    var x: i64 = 10;
    var y: i64 = 2;
    var z: i64 = divide(x, y);

    /* Error check */
    if (z == -1) {
        return 1;  /* error */
    }

    /* Safe division with error handling */
    var w: i64 = safe_divide(10, 0);
    return w;
}

